-- 3. on db-b
SELECT pg_promote(wait => true, wait_seconds => 60);   -- t
SELECT pg_is_in_recovery();                              -- f: it is a primary
SELECT pg_create_physical_replication_slot('db_c', true);
SELECT pg_create_physical_replication_slot('db_a', true);

-- 4. on db-c
ALTER SYSTEM SET primary_conninfo = 'host=db-b port=5432 user=replicator application_name=db_c';
ALTER SYSTEM SET primary_slot_name = 'db_c';
SELECT pg_reload_conf();
